		GitLabSecurityRealm realm = new GitLabSecurityRealm();

		String node;
		String value;

		while (reader.hasMoreChildren()) {
			reader.moveDown();
			node = reader.getNodeName();
			value = reader.getValue();
			setValue(realm, node, value);
			reader.moveUp();
		}

		return realm;
	}

